"""Build-time relocation of user-supplied stock wrappers; generated bytes stay local."""
from pathlib import Path
import struct,subprocess,json,sys
from capstone import *
from capstone.arm import *
from elftools.elf.elffile import ELFFile
import ziglang
from config import HERE,PAYLOAD
STOCK=PAYLOAD.read_bytes()
CS=Cs(CS_ARCH_ARM,CS_MODE_THUMB);CS.detail=True
DEST=0x2031a800;TONE=0x20319d00
def instructions(entries):
 todo=list(entries);found={}
 while todo:
  at=todo.pop()
  while at not in found:
   i=next(CS.disasm(STOCK[at:at+4],at,count=1));found[at]=i
   if i.id in [ARM_INS_B,ARM_INS_BL,ARM_INS_CBZ,ARM_INS_CBNZ]:
    target=i.operands[-1].imm
    if i.id!=ARM_INS_BL and min(entries)<=target<max(entries)+0x600:todo.append(target)
    if i.id==ARM_INS_B and i.cc==ARM_CC_AL:break
   if i.id==ARM_INS_BX or (i.id==ARM_INS_POP and any(o.type==ARM_OP_REG and o.reg==ARM_REG_PC for o in i.operands)):break
   at+=i.size
 return found
def compile_amp(amp):
 desc=struct.unpack_from('<8I',STOCK,0x1ab60+32*amp);entries=[desc[7]&~1,desc[6]&~1];ins=instructions(entries)
 source=['.syntax unified','.thumb','.fpu vfpv3-d16','.text','.global amp_init,amp_process']
 literals={};stubs={};provenance=[]
 for at,i in sorted(ins.items()):
  source.append(f'L{at:x}:')
  if at==entries[0]:source+=['.thumb_func','amp_init:']
  if at==entries[1]:source+=['.thumb_func','amp_process:']
  # These stock writes assign the same literal +0 on every block. The local
  # recipe initializes the corresponding resource words once instead.
  if at in [0x20202,0x20212,0x1d036,0x1d03c]:source.append('nop');continue
  if i.id in [ARM_INS_B,ARM_INS_BL,ARM_INS_CBZ,ARM_INS_CBNZ]:
   target=i.operands[-1].imm
   if target in ins:label=f'L{target:x}'
   else:
    label=f'S{target:x}';stubs[target]=label
   mnemonic=i.mnemonic.replace('.w','')
   prefix=i.op_str.rsplit(',',1)[0]+',' if i.id in [ARM_INS_CBZ,ARM_INS_CBNZ] else ''
   source.append(f'{mnemonic} {prefix}{label}');continue
  pc=[o for o in i.operands if o.type==ARM_OP_MEM and o.mem.base==ARM_REG_PC]
  if pc:
   assert len(pc)==1 and i.id in [ARM_INS_LDR,ARM_INS_VLDR],(hex(at),i.mnemonic)
   loc=((at+4)&~3)+pc[0].mem.disp
   n=8 if i.op_str.startswith('d') else 4;literals[loc]=max(n,literals.get(loc,0))
   source.append(f'{i.mnemonic} {i.op_str.split(",")[0]}, P{loc:x}');continue
  assert not any(o.type==ARM_OP_REG and o.reg==ARM_REG_PC for o in i.operands) or i.id==ARM_INS_POP,(hex(at),i.mnemonic,i.op_str)
  # Instructions are read from the user's stock image, not bundled upstream.
  source.append('.byte '+','.join(str(x) for x in i.bytes));provenance.append((at,len(i.bytes),f'L{at:x}'))
 source.append('.balign 4')
 def immediate(reg,value):
  source.extend([f'movw {reg}, #{value&65535}',f'movt {reg}, #{value>>16}'])
 for target,label in stubs.items():
  source.append(label+':')
  if target==0x464:immediate('r0',TONE)
  if target==0x2590:immediate('r3',TONE)
  if target==0x2404:immediate('r2',desc[4])
  if target in [0x1aa0,0x1bd0,0x235a]:immediate('r0',desc[4])
  immediate('r12',target|1);source.append('bx r12')
 source+=['.ltorg','.balign 8']
 for at,n in sorted(literals.items()):
  source.append(f'P{at:x}: .byte '+','.join(str(x) for x in STOCK[at:at+n]));provenance.append((at,n,f'P{at:x}'))
 folder=HERE/'wrappers';folder.mkdir(exist_ok=True)
 asm=folder/f'{amp}.S';asm.write_text('\n'.join(source)+'\n')
 subprocess.run(['clang','--target=arm-none-eabi','-mcpu=cortex-m7','-mthumb','-mfpu=vfpv3-d16','-mfloat-abi=hard','-c',str(asm),'-o',str(folder/f'{amp}.o')],check=True)
 ld=folder/'wrapper.ld';ld.write_text(f'SECTIONS {{ .text {DEST:#x} : {{ *(.text*) }} /DISCARD/ : {{ *(.ARM.exidx*) }} }}')
 elf=folder/f'{amp}.elf'
 subprocess.run([str(Path(ziglang.__path__[0])/'zig'),'cc','-target','thumb-freestanding-eabihf','-mcpu=cortex_m7','-nostdlib','-Wl,--build-id=none','-Wl,-e,amp_init','-Wl,-T,'+str(ld),str(folder/f'{amp}.o'),'-o',str(elf)],check=True,capture_output=True)
 with elf.open('rb') as f:
  e=ELFFile(f);data=e.get_section_by_name('.text').data();sym={s.name:s['st_value'] for s in e.get_section_by_name('.symtab').iter_symbols()}
 assert len(data)<=0x7e0,(amp,len(data))
 (folder/f'{amp}.bin').write_bytes(data)
 return dict(amp=amp,bytes=len(data),init=sym['amp_init'],process=sym['amp_process'],descriptor=list(desc),instructions=len(ins),original_fragments=[dict(source=at,length=n,offset=sym[label]-DEST) for at,n,label in provenance])
if __name__=='__main__':
 rows=[]
 for amp in range(1,26):
  row=compile_amp(amp);rows.append(row);print({k:v for k,v in row.items() if k!='original_fragments'},flush=True)
 (HERE/'wrappers/manifest.json').write_text(json.dumps(rows,indent=2)+'\n')
